Count Good Numbers.source:
import java.util.*;

public class Solution {
  private static long power(long x, long n) {
    long ans = 1, mod = 1000000007L;
    while (n > 0) {
      if ((n & 1) == 1) ans = ans * x % mod;
      x = x * x % mod;
      n >>= 1;
    }
    return ans;
  }

  public static long solve(long n) {
    if (n < 0) throw new IllegalArgumentException();
    return power(5, n / 2 + n % 2) * power(4, n / 2) % 1000000007L;
  }

  public static void main(String[] args) {
    System.out.println(solve(4));
  }
}

Reverse a Stack.source:
import java.util.*;

public class Solution {
  private static void bottom(Deque<Integer> stack, int x) {
    if (stack.isEmpty()) {
      stack.push(x);
      return;
    }
    int y = stack.pop();
    bottom(stack, x);
    stack.push(y);
  }

  public static void solve(Deque<Integer> stack) {
    if (stack.isEmpty()) return;
    int x = stack.pop();
    solve(stack);
    bottom(stack, x);
  }

  public static void main(String[] args) {
    Deque<Integer> s = new ArrayDeque<>(Arrays.asList(1, 2, 3));
    solve(s);
    System.out.println(s);
  }
}

