import java.util.*;

public class Solution {
  private static final String[] MAP = {
    "", "", "abc", "def", "ghi", "jkl", "mno", "pqrs", "tuv", "wxyz"
  };

  private static void dfs(String digits, int i, StringBuilder p, List<String> out) {
    if (i == digits.length()) {
      out.add(p.toString());
      return;
    }
    char digit = digits.charAt(i);
    if (digit < '2' || digit > '9') throw new IllegalArgumentException();
    for (char c : MAP[digit - '0'].toCharArray()) {
      p.append(c);
      dfs(digits, i + 1, p, out);
      p.deleteCharAt(p.length() - 1);
    }
  }

  public static List<String> solve(String digits) {
    List<String> out = new ArrayList<>();
    if (!digits.isEmpty()) dfs(digits, 0, new StringBuilder(), out);
    return out;
  }

  public static void main(String[] args) {
    System.out.println(solve("23"));
  }
}

Palindrome partitioning.source:
import java.util.*;

public class Solution {
  private static boolean palindrome(String s, int l, int r) {
    while (l < r) if (s.charAt(l++) != s.charAt(r--)) return false;
    return true;
  }

  private static void dfs(String s, int start, List<String> p, List<List<String>> out) {
    if (start == s.length()) {
      out.add(new ArrayList<>(p));
      return;
    }
    for (int end = start; end < s.length(); end++)
      if (palindrome(s, start, end)) {
        p.add(s.substring(start, end + 1));
        dfs(s, end + 1, p, out);
        p.remove(p.size() - 1);
      }
  }

  public static List<List<String>> solve(String s) {
    List<List<String>> out = new ArrayList<>();
    dfs(s, 0, new ArrayList<>(), out);
    return out;
  }

  public static void main(String[] args) {
    System.out.println(solve("aab"));
  }
}

Word Search.source:
import java.util.*;

public class Solution {
  private static boolean dfs(char[][] a, String word, int i, int r, int c, boolean[][] used) {
    if (i == word.length()) return true;
    if (r < 0
        || r == a.length
        || c < 0
        || c == a[0].length
        || used[r][c]
        || a[r][c] != word.charAt(i)) return false;
    used[r][c] = true;
    boolean found =
        dfs(a, word, i + 1, r + 1, c, used)
            || dfs(a, word, i + 1, r - 1, c, used)
            || dfs(a, word, i + 1, r, c + 1, used)
            || dfs(a, word, i + 1, r, c - 1, used);
    used[r][c] = false;
    return found;
  }

  public static boolean solve(char[][] a, String word) {
    if (word.isEmpty()) return true;
    if (a.length == 0 || a[0].length == 0) return false;
    boolean[][] used = new boolean[a.length][a[0].length];
    for (int r = 0; r < a.length; r++)
      for (int c = 0; c < a[0].length; c++) if (dfs(a, word, 0, r, c, used)) return true;
    return false;
  }

  public static void main(String[] args) {
    System.out.println(
        solve(
            new char[][] {{'A', 'B', 'C', 'E'}, {'S', 'F', 'C', 'S'}, {'A', 'D', 'E', 'E'}},
            "ABCCED"));
  }
}

N Queen.source:
import java.util.*;

public class Solution {
  private static void dfs(
      int r, char[][] board, boolean[] col, boolean[] down, boolean[] up, List<List<String>> out) {
    int n = board.length;
    if (r == n) {
      List<String> rows = new ArrayList<>();
      for (char[] row : board) rows.add(new String(row));
      out.add(rows);
      return;
    }
    for (int c = 0; c < n; c++)
      if (!col[c] && !down[r - c + n - 1] && !up[r + c]) {
        col[c] = down[r - c + n - 1] = up[r + c] = true;
        board[r][c] = 'Q';
        dfs(r + 1, board, col, down, up, out);
        board[r][c] = '.';
        col[c] = down[r - c + n - 1] = up[r + c] = false;
      }
  }

  public static List<List<String>> solve(int n) {
    if (n < 0) throw new IllegalArgumentException();
    char[][] b = new char[n][n];
    for (char[] row : b) Arrays.fill(row, '.');
    List<List<String>> out = new ArrayList<>();
    dfs(
        0,
        b,
        new boolean[n],
        new boolean[Math.max(0, 2 * n - 1)],
        new boolean[Math.max(0, 2 * n - 1)],
        out);
    return out;
  }

  public static void main(String[] args) {
    System.out.println(solve(4).size());
  }
}

Rat in a Maze.source:
import java.util.*;

public class Solution {
  private static final int[] DR = {1, 0, 0, -1}, DC = {0, -1, 1, 0};
  private static final char[] DIR = {'D', 'L', 'R', 'U'};

  private static void dfs(
      int[][] a, int r, int c, boolean[][] seen, StringBuilder p, List<String> out) {
    int n = a.length;
    if (r == n - 1 && c == n - 1) {
      out.add(p.toString());
      return;
    }
    seen[r][c] = true;
    for (int d = 0; d < 4; d++) {
      int x = r + DR[d], y = c + DC[d];
      if (x >= 0 && y >= 0 && x < n && y < n && a[x][y] == 1 && !seen[x][y]) {
        p.append(DIR[d]);
        dfs(a, x, y, seen, p, out);
        p.deleteCharAt(p.length() - 1);
      }
    }
    seen[r][c] = false;
  }

  public static List<String> solve(int[][] a) {
    List<String> out = new ArrayList<>();
    int n = a.length;
    if (n == 0) return out;
    for (int[] row : a) if (row.length != n) throw new IllegalArgumentException();
    if (a[0][0] == 1 && a[n - 1][n - 1] == 1)
      dfs(a, 0, 0, new boolean[n][n], new StringBuilder(), out);
    return out;
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[][] {{1, 0}, {1, 1}}));
  }
}

M Coloring Problem.source:
import java.util.*;

public class Solution {
  private static boolean dfs(boolean[][] graph, int v, int[] color, int m) {
    if (v == graph.length) return true;
    for (int c = 1; c <= m; c++) {
      boolean valid = true;
      for (int u = 0; u < graph.length; u++)
        if ((graph[v][u] || graph[u][v]) && (u == v || color[u] == c)) {
          valid = false;
          break;
        }
      if (valid) {
        color[v] = c;
        if (dfs(graph, v + 1, color, m)) return true;
        color[v] = 0;
      }
    }
    return false;
  }

  public static boolean solve(boolean[][] graph, int m) {
    if (m < 0) throw new IllegalArgumentException();
    return dfs(graph, 0, new int[graph.length], m);
  }

  public static void main(String[] args) {
    System.out.println(
        solve(new boolean[][] {{false, true, true}, {true, false, true}, {true, true, false}}, 3));
  }
}

Sudoku Solver.source:
import java.util.*;

public class Solution {
  private static boolean valid(char[][] a, int r, int c, char x) {
    for (int i = 0; i < 9; i++)
      if (a[r][i] == x || a[i][c] == x || a[3 * (r / 3) + i / 3][3 * (c / 3) + i % 3] == x)
        return false;
    return true;
  }

  private static boolean dfs(char[][] a) {
    for (int r = 0; r < 9; r++)
      for (int c = 0; c < 9; c++)
        if (a[r][c] == '.') {
          for (char x = '1'; x <= '9'; x++)
            if (valid(a, r, c, x)) {
              a[r][c] = x;
              if (dfs(a)) return true;
              a[r][c] = '.';
            }
          return false;
        }
    return true;
  }

  public static boolean solve(char[][] a) {
    if (a.length != 9) throw new IllegalArgumentException();
    for (char[] row : a) if (row.length != 9) throw new IllegalArgumentException();
    for (int r = 0; r < 9; r++)
      for (int c = 0; c < 9; c++)
        if (a[r][c] != '.') {
          char x = a[r][c];
          a[r][c] = '.';
          boolean ok = x >= '1' && x <= '9' && valid(a, r, c, x);
          a[r][c] = x;
          if (!ok) return false;
        }
    return dfs(a);
  }

  public static void main(String[] args) {
    char[][] a = {
      "53..7....".toCharArray(),
      "6..195...".toCharArray(),
      ".98....6.".toCharArray(),
      "8...6...3".toCharArray(),
      "4..8.3..1".toCharArray(),
      "7...2...6".toCharArray(),
      ".6....28.".toCharArray(),
      "...419..5".toCharArray(),
      "....8..79".toCharArray()
    };
    System.out.println(solve(a));
    System.out.println(new String(a[0]));
  }
}

